/* === eventListener.js === */ function attachRegisterFormHandler() { const form = document.getElementById('registerForm'); if (!form) return; form.addEventListener('submit', function(e) { e.preventDefault(); const password = form.password.value.trim(); const confirmPassword = form.confirmPassword.value.trim(); const errorDiv = document.getElementById('passwordError'); if (password !== confirmPassword) { errorDiv.style.display = 'block'; } else { errorDiv.style.display = 'none'; console.log("Création de compte avec succès !"); closeModal(); } }); } /* === main.js === */ function togglePassword(toggleElement) { const input = toggleElement.previousElementSibling; if (input.type === "password") { input.type = "text"; toggleElement.textContent = "🙈"; } else { input.type = "password"; toggleElement.textContent = "👁️"; } } /* === modal.config.js === */ const modalConfigs = { debug: { title: "Debug", content: "<p>Information de débogage pour développeur.</p>", width: "500px", color: "#888", icon: "🛠️", position: "top", closeButtonPosition: "" }, info: { title: "Information", content: "<p>Ceci est un message d'information important.</p>", width: "400px", color: "#2196F3", icon: "ℹ️", position: "top", closeButtonPosition: "" }, notice: { title: "Notice", content: "<p>Petit avertissement : tout fonctionne mais attention.</p>", width: "400px", color: "#4CAF50", icon: "📌", position: "top", closeButtonPosition: "" }, warning: { title: "Avertissement", content: "<p>Attention, un problème potentiel a été détecté.</p>", width: "400px", color: "#FF9800", icon: "⚠️", position: "top", closeButtonPosition: "" }, error: { title: "Erreur", content: "<p>Une erreur est survenue. Merci de réessayer plus tard.</p>", width: "400px", color: "#f44336", icon: "❌", position: "top", closeButtonPosition: "" }, critical: { title: "Critique", content: "<p>Erreur critique. Intervention nécessaire.</p>", width: "400px", color: "#D32F2F", icon: "🚨", position: "top", closeButtonPosition: "" }, alert: { title: "Alerte", content: "<p>Alerte système : agissez immédiatement.</p>", width: "400px", color: "#C2185B", icon: "🚨", position: "top", closeButtonPosition: "" }, emergency: { title: "Urgence", content: "<p>Système indisponible. Intervention urgente requise !</p>", width: "400px", color: "#B71C1C", icon: "🆘", position: "top", closeButtonPosition: "" }, success: { title: "Succès", content: "<p>Opération réussie !</p>", width: "400px", color: "#4CAF50", icon: "✅", position: "top", closeButtonPosition: "" }, confirm: { title: "Confirmation", content: "<p>Êtes-vous sûr de vouloir continuer ?</p>", width: "400px", color: "#FF9800", icon: "❓", position: "top", closeButtonPosition: "" }, login: { title: "Connexion requise", content: ` <form id="loginForm" class="login-form"> <input type="text" id="username" name="username" placeholder="Nom d'utilisateur" required> <div class="password-field"> <input type="password" id="password" name="password" placeholder="Mot de passe" required> <span class="toggle-password" onclick="togglePassword(this)">👁️</span> </div> <button type="submit">Connexion</button> <p class="create-account-link"> Pas encore de compte ? <a href="#" onclick="openRegisterModal()">Créer un compte</a> </p> </form> `, color: "#333", width: "400px", icon: "🔑", position: "center", closeButtonPosition: "", closeButtonVisibility: false, }, register: { title: "Création de compte", content: ` <form id="registerForm" class="registrer-form"> <input type="text" id="newUsername" name="username" placeholder="Nom d'utilisateur" required> <div class="password-field"> <input type="password" id="newPassword" name="password" placeholder="Mot de passe" required> <span class="toggle-password" onclick="togglePassword(this)">👁️</span> </div> <div class="password-field"> <input type="password" id="confirmPassword" name="confirmPassword" placeholder="Confirmer le mot de passe" required> <span class="toggle-password" onclick="togglePassword(this)">👁️</span> </div> <div id="passwordError" style="color: red; display: none; margin-top: 5px;"> Les mots de passe ne correspondent pas. </div> <button type="submit">Créer le compte</button> </form> `, color: "green", width: "400px", icon: "📝", position: "center", closeButtonPosition: "", closeButtonVisibility: true, backButton: true, backTarget: "login" }, }; /* === modal.js === */ function openModal(type, customContent = null) { closeModal(); const config = modalConfigs[type]; if (!config) { console.error(`Configuration pour le type '${type}' introuvable.`); return; } const modal = document.createElement("div"); modal.classList.add("modal-overlay"); modal.classList.add(`overlay-${config.position || 'center'}`); if (config.position === "top") { modal.classList.add("modal-fixed-top"); } const positionClass = config.position ? `modal-${config.position}` : 'modal-center'; let headerHTML = ""; if (config.icon) { headerHTML = `<h2 style="color: ${config.color || '#333'};">${config.icon} ${config.title}</h2>`; } else { headerHTML = `<h2>${config.title}</h2>`; } const bodyContent = customContent !== null ? customContent : config.content; modal.innerHTML = ` <div class="modal-content ${positionClass}" style="width: ${config.width || '400px'}; border-top: 6px solid ${config.color || '#333'};"> <div class="modal-header-bar"> ${config.backButton ? `<button class="modal-back" onclick="openModal('${config.backTarget || 'login'}')">←</button>` : ''} <button class="modal-close" onclick="closeModal()">×</button> </div> ${headerHTML} <div class="modal-body"> ${bodyContent} </div> </div> `; modal.addEventListener("click", function (e) { if (e.target === modal) { closeModal(); } }); document.body.appendChild(modal); if (type === 'login') { const form = document.getElementById('loginForm'); if (form) { form.addEventListener('submit', function(e) { e.preventDefault(); const username = form.username.value.trim(); const password = form.password.value.trim(); console.log("Tentative de login avec", username, password); closeModal(); }); } } if (type === 'register') { attachRegisterFormHandler(); } } function closeModal() { const modal = document.querySelector(".modal-overlay"); if (modal) { modal.remove(); } } function openRegisterModal() { openModal('register'); }